15.3 Cross-References
@tbl-name     # Reference table
@fig-name     # Reference figure  
@sec-name     # Reference section
@eq-name      # Reference equation

B2 · The basket — when_any() / when_all()

basket &lt;- retail |&gt;
  filter_out(category == "non-food") |&gt;
  filter(
    when_any(
      when_all(unit_std == "per kg",    category != "milk and dairy"),
      when_all(unit_std == "per litre",
               str_detect(commodity, regex("oil|ghee", ignore_case = TRUE)))
    )
  )

Read it aloud: keep a row if (it’s per-kg and not dairy) OR (it’s per-litre and it’s an oil/ghee). The code has the same shape as the sentence — that’s the entire design intent of these two verbs.

B2 · Winsorise with replace_when()

basket &lt;- basket |&gt;
  mutate(
    price_w = replace_when(
      price_std,
      price_std &gt; quantile(price_std, 0.999, na.rm = TRUE)
      ~ quantile(price_std, 0.999, na.rm = TRUE)
    ),
    .by = c(commodity, unit_std)
  )

basket |&gt;
  filter(price_std != price_w) |&gt;
  select(date, market, commodity, price_std, price_w) |&gt;
  arrange(desc(price_std))

replace_when() is partial — everything not matched passes through unchanged. Always print what changed. Winsorising silently is not defensible; winsorising visibly is.

B3 · market_meta — authoritative, not reconstructed

market_meta &lt;- markets |&gt;
  mutate(province = recode_values(admin1,
                                  from = province_lookup$from,
                                  to   = province_lookup$to)) |&gt;
  select(market_id, market, admin1, admin2, province, latitude, longitude) |&gt;
  mutate(reporting = !market_id %in% markets_no_data$market_id)

market_meta |&gt; filter(is.na(province), !is.na(admin1)) |&gt; count(admin1, sort = TRUE)
market_meta |&gt; count(reporting)

Built from the markets file, not from distinct() on basket. A market_meta built from basket silently loses every market with zero observations. This version carries a reporting flag instead — nothing is lost, and the map later can show it.

B3 · The wheat frames

wheat &lt;- basket |&gt;
  filter(str_detect(commodity, regex("^wheat flour", ignore_case = TRUE)))

wheat_market &lt;- wheat |&gt;
  summarise(price_pkr = mean(price_w, na.rm = TRUE),
            .by = c(date, market, province))

wheat_national &lt;- national_monthly |&gt;
  filter(str_detect(commodity, regex("^wheat flour", ignore_case = TRUE)))

Three grains, named explicitly: wheat is one row per observation, wheat_market one row per market-month, wheat_national one row per month.

B4 · Build the chained index

wheat_chained &lt;- wheat_market |&gt;
  complete(market, date) |&gt;
  arrange(market, date) |&gt;
  mutate(rel = price_pkr / lag(price_pkr), .by = market) |&gt;
  summarise(gm        = exp(mean(log(rel), na.rm = TRUE)),
            n_matched = sum(!is.na(rel)),
            .by = date) |&gt;
  arrange(date) |&gt;
  mutate(gm    = replace_when(gm, is.na(gm) ~ 1),
         index = 100 * cumprod(gm))

For each market compute its own month-on-month relative, take the geometric mean of relatives across only markets present in both months, then chain with cumprod(). This is composition-safe by construction.

B4 · Per-market index (a different question)

wheat_market_index &lt;- wheat_market |&gt;
  filter(!is.na(price_pkr)) |&gt;
  arrange(market, date) |&gt;                      # load-bearing
  mutate(index = 100 * price_pkr / first(price_pkr), .by = market)

.by does not reorder rows. first() returns the first row as currently sorted — the arrange() before it is not decorative, it’s required.

B5 · Distances between markets

markets_sf &lt;- market_meta |&gt;
  filter_out(is.na(latitude) | is.na(longitude)) |&gt;
  st_as_sf(coords = c("longitude", "latitude"), crs = 4326)

dist_km &lt;- st_distance(markets_sf) |&gt;
  units::set_units("km") |&gt;
  units::drop_units()
dimnames(dist_km) &lt;- list(markets_sf$market, markets_sf$market)

pair_distance &lt;- dist_km |&gt;
  as_tibble(rownames = "market_a") |&gt;
  pivot_longer(-market_a, names_to = "market_b", values_to = "distance_km") |&gt;
  filter(market_a &lt; market_b)

market_a &lt; market_b (string comparison) keeps one row per pair instead of two mirrored rows — a small trick worth remembering for any symmetric pairwise table.

B5 · Law of one price

pair_gaps &lt;- wheat_market |&gt;
  select(date, market, price_pkr) |&gt;
  inner_join(wheat_market |&gt; select(date, market, price_pkr),
             by           = join_by(date),
             relationship = "many-to-many",     # intentional cross, declared
             suffix       = c("_a", "_b")) |&gt;
  filter(market_a &lt; market_b) |&gt;
  mutate(gap = abs(price_pkr_a - price_pkr_b)) |&gt;
  summarise(mean_gap = mean(gap, na.rm = TRUE), n_months = n(),
            .by = c(market_a, market_b)) |&gt;
  filter(n_months &gt;= 24) |&gt;
  inner_join(pair_distance, by = join_by(market_a, market_b))

summary(lm(mean_gap ~ distance_km, data = pair_gaps))

relationship = "many-to-many" is declared, not suppressed — dplyr warns on unexpected many-to-many joins because they’re usually bugs. Here it’s the deliberate point: cross every market against every other market.

B6 · Affordability

wages &lt;- prices_actual |&gt;
  filter(str_detect(commodity, regex("wage", ignore_case = TRUE))) |&gt;
  summarise(wage_pkr = mean(price, na.rm = TRUE), .by = c(date, market))

affordability &lt;- wheat_market |&gt;
  inner_join(wages, by = join_by(date, market)) |&gt;
  mutate(kg_per_day_wage = wage_pkr / price_pkr)

c(wheat_market = nrow(wheat_market), affordability = nrow(affordability))

The wage series lives inside non-food — exactly why it wasn’t thrown away in B2. inner_join() restricts you to months where both a price and a wage were reported; the row-count comparison shows what that costs.

B7 · Recode province names, audit

pak_admin &lt;- pak_states |&gt;
  mutate(province = recode_values(name,
                                  from = province_lookup$from,
                                  to   = province_lookup$to),
         status   = "Administered by Pakistan") |&gt;
  select(province, status, geometry)

# polygons our lookup does not recognise
pak_admin |&gt; st_drop_geometry() |&gt; filter(is.na(province))

Same province_lookup as B2 — the payoff for centralising it. Must be empty; anything else is a spelling the lookup hasn’t seen yet.

B7 · Dissolve Jammu & Kashmir into one polygon

jk_geometry &lt;- ind_states |&gt;
  filter(str_detect(name, regex("jammu|kashmir|ladakh", ignore_case = TRUE))) |&gt;
  st_geometry() |&gt;
  st_union()

jammu_kashmir &lt;- st_sf(
  province = "Jammu & Kashmir",
  status   = "Disputed territory — no reporting market",
  geometry = jk_geometry
)

st_union() dissolves the internal India-administered subdivisions so no internal line appears on a Pakistani-facing map. st_sf() builds the one-row spatial frame explicitly, sidestepping any class-dropping quirks in bind_rows() on sf objects.

B8 · Small multiples over time

snapshot_years &lt;- c(2010, 2015, 2020, max(province_year$year))

map_panel &lt;- province_year |&gt;
  filter(str_detect(commodity, regex("^wheat flour", ignore_case = TRUE)),
         year %in% snapshot_years) |&gt;
  summarise(price_pkr = mean(price_pkr, na.rm = TRUE), .by = c(province, year))

p_map_facets &lt;- base_map |&gt;
  cross_join(tibble(year = snapshot_years)) |&gt;   # complete polygon-year grid
  left_join(map_panel, by = join_by(province, year)) |&gt;
  st_as_sf() |&gt;
  ggplot() +
  geom_sf(aes(fill = price_pkr), colour = "white", linewidth = 0.2) +
  facet_wrap(~ year) +
  coord_sf(crs = pak_crs) +
  labs(title = "Wheat flour price by province over time", caption = map_caption)

cross_join() builds the complete polygon-year grid first. Join data onto polygons the other way round and a province with no observation in a given year simply vanishes from that panel — the reader can’t tell absence of data from absence of territory.

Saving Cleaned Data

# Save as CSV
export(nhanes_clean, "nhanes_cleaned.csv")

# Save as RDS (preserves R object types)
export(nhanes_clean, "nhanes_cleaned.rds")

# Save as Stata file
export(nhanes_clean, "nhanes_cleaned.dta")

# Save as Excel
export(nhanes_clean, "nhanes_cleaned.xlsx")

Step 6: Focus on the Three Core Variables

mpi |&gt;
  select(district, mpi, h_incidence, a_intensity) |&gt;
  head(10)

select() narrows the data to the columns we need.

Step 7: Rank Districts by MPI

mpi |&gt;
  select(district, province, mpi) |&gt;
  arrange(desc(mpi)) |&gt;
  head(10)

arrange(desc()) sorts from highest to lowest.

Step 8: Filter by Province

mpi |&gt;
  filter(province == "Balochistan") |&gt;
  select(district, mpi, h_incidence, a_intensity) |&gt;
  arrange(desc(mpi))

filter() keeps only rows meeting a condition.

Step 9: Province-Level Averages

mpi |&gt;
  summarise(
    avg_mpi = mean(mpi),
    avg_h   = mean(h_incidence),
    avg_a   = mean(a_intensity),
    .by = province
  ) |&gt;
  arrange(desc(avg_mpi))

.by = groups without a separate group_by() / ungroup() pair.

Corrected date handling

pakistan_floods &lt;- pakistan_floods |&gt;
  mutate(
    start_date = lubridate::mdy(start_date),
    end_date   = lubridate::mdy(end_date),
    month      = lubridate::floor_date(start_date, unit = "month"),
    .keep = "unused"          # drop the unreliable `mon-yr` column
  )

pakistan_floods |&gt;
  select(start_date, end_date, month) |&gt;
  head()

Note the order: start_date has to be parsed before month can be derived from it — the original code computed month from mon-yr in the same mutate() call where start_date was still character text.

3.1 Why you cannot just read_csv() the web page
https://data.humdata.org/dataset/wfp-food-prices-for-pakistan is a landing page. Pointing read_csv() at it downloads HTML. HDX runs on CKAN, which exposes a JSON API, and the API is the stable, scriptable way in.

hdx_resource_url &lt;- function(dataset_id,
                             include = "food_prices",
                             exclude = "qc") {
  pkg &lt;- fromJSON(
    paste0("https://data.humdata.org/api/3/action/package_show?id=", dataset_id)
  )

  resources &lt;- as_tibble(pkg$result$resources)

  resources |&gt;
    filter(str_detect(url, regex(include, ignore_case = TRUE))) |&gt;
    filter_out(str_detect(url, regex(exclude, ignore_case = TRUE))) |&gt;
    slice(1) |&gt;
    pull(url)
}

Two things to notice in that pipeline:

The positive condition uses filter(), the negative one uses filter_out(). That is the whole design intent of the new verb: the function name, not a buried !, tells the reader whether rows are being kept or dropped.
HDX publishes a “QuickCharts” (qc) subset alongside the full file. It has the same name pattern and will silently give you a truncated dataset if you take the first match blindly. This is a very common and very quiet failure mode.

4.4 Missingness audit

prices |&gt;
  summarise(across(everything(), \(x) sum(is.na(x)))) |&gt;
  pivot_longer(everything(), names_to = "column", values_to = "n_missing") |&gt;
  mutate(pct_missing = n_missing / nrow(prices)) |&gt;
  filter(n_missing &gt; 0) |&gt;
  arrange(desc(n_missing))

5.2 Decision 2 — retail versus wholesale
This is the decision most often missed. Retail and wholesale prices for the same commodity in the same month differ by a margin. If you average across both, your “national price” moves whenever the mix of reporting types changes — even if no actual price moved.

prices_actual |&gt;
  count(pricetype, commodity) |&gt;
  pivot_wider(names_from = pricetype, values_from = n, values_fill = 0) |&gt;
  arrange(desc(Retail))


retail &lt;- prices_actual |&gt;
  filter(pricetype == "Retail")

Analyse wholesale separately if you need it. Do not pool.

5.4 Decision 4 — the panel is unbalanced
This is the subtlest one. Markets enter and leave the sample. A simple mean(price) across whatever markets reported this month is a composition-varying statistic: if an expensive market starts reporting in March, your national average jumps in March with no price change anywhere.

coverage &lt;- retail |&gt;
  filter(!is.na(price_std)) |&gt;
  summarise(
    n_obs     = n(),
    n_months  = n_distinct(date),
    first_obs = min(date),
    last_obs  = max(date),
    .by = c(commodity, market)
  ) |&gt;
  arrange(commodity, market)

coverage


retail |&gt;
  filter(str_detect(commodity, regex("wheat flour", ignore_case = TRUE))) |&gt;
  distinct(market, date) |&gt;
  ggplot(aes(date, fct_rev(fct_infreq(market)))) +
  geom_point(size = 0.6, alpha = 0.7) +
  labs(
    title    = "Who reports, and when",
    subtitle = "Wheat flour, retail — each dot is one market-month",
    x = NULL, y = NULL,
    caption  = "Gaps and late entries are why a raw cross-market mean is unsafe"
  )

Look at that plot before you compute a single average. We return to the fix in Section 12.

6.1 when_any() and when_all()
filter() combines its conditions with &. To get | you used to need parentheses and one long unreadable expression. when_any() and when_all() let you build the boolean structure as nested, named pieces.
Our staple basket: food items priced per kilo, plus cooking oils and ghee priced per litre.

basket &lt;- retail |&gt;
  filter_out(category == "non-food") |&gt;
  filter(
    when_any(
      when_all(unit_std == "per kg",    category != "milk and dairy"),
      when_all(unit_std == "per litre", str_detect(commodity, regex("oil|ghee", ignore_case = TRUE)))
    )
  )

basket |&gt; count(commodity, unit_std, sort = TRUE)

Read that aloud: keep a row if (it is per-kg and not dairy) or (it is per-litre and it is an oil or ghee). The code now has the same shape as the sentence. when_any() and when_all() are ordinary vector functions — you can use them in mutate(), if_else(), anywhere.

6.3 The lookup-table interface
For anything with more than a handful of cases, recode_values() accepts from/to vectors instead of formulas. A tribble() where a cell holds a vector becomes a list column, and recode_values() treats each vector as “any of these map to this”. This is the cleanest way to handle spelling variants.

province_lookup &lt;- tribble(
  ~from,                                                              ~to,
  c("Punjab"),                                                        "Punjab",
  c("Sindh"),                                                         "Sindh",
  c("Khyber Pakhtunkhwa", "N.W.F.P.", "NWFP",
    "Federally Administered Tribal Areas", "F.A.T.A."),               "KP",
  c("Balochistan", "Baluchistan"),                                    "Balochistan",
  c("Islamabad", "F.C.T.", "Islamabad Capital Territory"),            "Islamabad",
  c("Azad Kashmir", "Azad Jammu and Kashmir", "AJK"),                 "Azad Jammu & Kashmir",
  c("Gilgit-Baltistan", "Northern Areas"),                            "Gilgit-Baltistan"
)

province_lookup
province_lookup$from   # note: a list column

One lookup, used twice — once on the price data, once on the map. That is the whole point: the crosswalk lives in exactly one place.

basket &lt;- basket |&gt;
  mutate(
    province = recode_values(
      admin1,
      from = province_lookup$from,
      to   = province_lookup$to
    )
  )

# Audit: anything unmatched?
basket |&gt;
  filter(is.na(province), !is.na(admin1)) |&gt;
  count(admin1, sort = TRUE)

If that audit returns rows, add them to the lookup. Once it is empty, switch on strict mode so the pipeline fails loudly if WFP ever renames a province:

basket |&gt;
  filter(!is.na(admin1)) |&gt;
  mutate(province = recode_values(
    admin1,
    from      = province_lookup$from,
    to        = province_lookup$to,
    unmatched = "error"
  )) |&gt;
  invisible()

6.4 replace_when() — surgical edits to one column
replace_when() is base::replace() with a grammar. Use it to winsorise implausible spikes without touching anything else:

basket &lt;- basket |&gt;
  mutate(
    price_w = replace_when(
      price_std,
      price_std &gt; quantile(price_std, 0.999, na.rm = TRUE)
        ~ quantile(price_std, 0.999, na.rm = TRUE)
    ),
    .by = c(commodity, unit_std)
  )

# What actually changed?
basket |&gt;
  filter(price_std != price_w) |&gt;
  select(date, market, commodity, unit_std, price_std, price_w) |&gt;
  arrange(desc(price_std))

Always print the rows you changed. Winsorising is a defensible choice; doing it invisibly is not.






TipWhy replace_when() and not case_when()



case_when() would force you to write a second branch — .default = price_std — to preserve the untouched values, and it would let you accidentally change the column’s type. replace_when() guarantees the output has the same type as the input and preserves everything you did not name.

7.1 Pick your reference commodity from the data, not from memory
Commodity labels are country-specific and change over time. Never hard-code a string you have not seen in the file.

basket |&gt;
  distinct(commodity, unit_std) |&gt;
  filter(str_detect(commodity, regex("wheat|rice|sugar|oil|ghee|lentil|pulse",
                                     ignore_case = TRUE))) |&gt;
  arrange(commodity) |&gt;
  print(n = Inf)

Copy the exact string you want from that output into the next chunk.

wheat &lt;- basket |&gt;
  filter(str_detect(commodity, regex("^wheat flour", ignore_case = TRUE)))

# Grain: one row per market-month
wheat_market &lt;- wheat |&gt;
  summarise(price_pkr = mean(price_w, na.rm = TRUE), .by = c(date, market, province))

# Grain: one row per month
wheat_national &lt;- national_monthly |&gt;
  filter(str_detect(commodity, regex("^wheat flour", ignore_case = TRUE)))

8.1 Month-on-month and year-on-year

national_monthly &lt;- national_monthly |&gt;
  arrange(commodity, date) |&gt;
  mutate(
    mom = price_pkr / lag(price_pkr)      - 1,
    yoy = price_pkr / lag(price_pkr, 12)  - 1,
    .by = commodity
  )







Warninglag() counts rows, not months



lag(price_pkr, 12) gives you the price twelve rows earlier. If a commodity has a reporting gap, that is not twelve months earlier — and your “year-on-year” number is quietly wrong. Make the panel complete first.



national_monthly &lt;- national_monthly |&gt;
  complete(commodity, date) |&gt;          # insert explicit NA rows for missing months
  arrange(commodity, date) |&gt;
  mutate(
    mom = price_pkr / lag(price_pkr)     - 1,
    yoy = price_pkr / lag(price_pkr, 12) - 1,
    .by = commodity
  )

Now a gap produces an honest NA instead of a fabricated growth rate. The habit generalises: any time you use lag(), lead(), diff() or cumsum() on a panel, complete the panel first.

8.2 Where were the big moves?

national_monthly |&gt;
  filter(!is.na(yoy)) |&gt;
  slice_max(yoy, n = 15) |&gt;
  select(date, commodity, price_pkr, yoy)

9.1 A genuine real price
To deflate you need a price index. World Bank WDI carries annual CPI for Pakistan; PBS publishes monthly CPI, which is better if you can get it into R.

cpi &lt;- WDI::WDI(
  country   = "PK",
  indicator = c(cpi = "FP.CPI.TOTL"),
  start     = 2004,
  end       = as.integer(format(Sys.Date(), "%Y"))
) |&gt;
  as_tibble() |&gt;
  select(year, cpi) |&gt;
  filter_out(is.na(cpi))

base_year &lt;- cpi |&gt; slice_max(year) |&gt; pull(year)
base_cpi  &lt;- cpi |&gt; filter(year == base_year) |&gt; pull(cpi)

wheat_real &lt;- wheat_national |&gt;
  summarise(price_pkr = mean(price_pkr, na.rm = TRUE), .by = year) |&gt;
  inner_join(cpi, by = join_by(year)) |&gt;
  mutate(price_real = price_pkr * base_cpi / cpi)

wheat_real |&gt;
  pivot_longer(c(price_pkr, price_real), names_to = "series", values_to = "value") |&gt;
  mutate(series = recode_values(series,
    "price_pkr"  ~ "Nominal",
    "price_real" ~ paste0("Real (", base_year, " prices)")
  )) |&gt;
  ggplot(aes(year, value, colour = series)) +
  geom_line(linewidth = 0.8) +
  scale_y_continuous(labels = label_number(prefix = "Rs ")) +
  labs(
    title    = "Wheat flour, nominal versus real",
    subtitle = "Deflated by headline CPI",
    x = NULL, y = "Rs per kg", colour = NULL
  )







NoteInterpret this carefully



Headline CPI contains food. Deflating a food price by headline CPI gives you the price of wheat flour relative to the general basket — a relative price, not a purchasing-power-adjusted price. That is usually what you want for a food security argument, but say so explicitly in your write-up.

12.2 Does distance explain price gaps?
The law of one price says that markets further apart should show bigger price gaps, bounded by transport costs. This is testable with what you already have.

markets_sf &lt;- market_meta |&gt;
  filter_out(is.na(latitude) | is.na(longitude)) |&gt;
  st_as_sf(coords = c("longitude", "latitude"), crs = 4326)

dist_km &lt;- st_distance(markets_sf) |&gt;
  units::set_units("km") |&gt;
  units::drop_units()

dimnames(dist_km) &lt;- list(markets_sf$market, markets_sf$market)

pair_distance &lt;- dist_km |&gt;
  as_tibble(rownames = "market_a") |&gt;
  pivot_longer(-market_a, names_to = "market_b", values_to = "distance_km") |&gt;
  filter(market_a &lt; market_b)


pair_gaps &lt;- wheat_market |&gt;
  select(date, market, price_pkr) |&gt;
  inner_join(
    wheat_market |&gt; select(date, market, price_pkr),
    by            = join_by(date),
    relationship  = "many-to-many",
    suffix        = c("_a", "_b")
  ) |&gt;
  filter(market_a &lt; market_b) |&gt;
  mutate(gap = abs(price_pkr_a - price_pkr_b)) |&gt;
  summarise(
    mean_gap = mean(gap, na.rm = TRUE),
    n_months = n(),
    .by = c(market_a, market_b)
  ) |&gt;
  filter(n_months &gt;= 24) |&gt;
  inner_join(pair_distance, by = join_by(market_a, market_b))

pair_gaps |&gt;
  ggplot(aes(distance_km, mean_gap)) +
  geom_point(alpha = 0.6) +
  geom_smooth(method = "lm", se = TRUE, linewidth = 0.6) +
  labs(
    title    = "Law of one price: do distant markets diverge?",
    subtitle = "Mean absolute wheat flour price gap against great-circle distance",
    x = "Distance between markets (km)", y = "Mean absolute gap (Rs/kg)"
  )


lm(mean_gap ~ distance_km, data = pair_gaps) |&gt; summary()

Note relationship = "many-to-many" in the join. dplyr 1.1+ warns on unexpected many-to-many joins because they are usually mistakes. Here it is intentional — we want every market crossed with every market within a month — so we say so. Never silence that warning by deleting it; declare intent instead.

12.3 A composition-safe index
Back to Decision 4. The fix for an unbalanced panel is a matched-sample chained index: compute the month-on-month price relative within each market, average those relatives across only the markets present in both months, then chain.

wheat_chained &lt;- wheat_market |&gt;
  complete(market, date) |&gt;                 # explicit gaps, so lag() is honest
  arrange(market, date) |&gt;
  mutate(rel = price_pkr / lag(price_pkr), .by = market) |&gt;
  summarise(
    gm        = exp(mean(log(rel), na.rm = TRUE)),   # geometric mean of relatives
    n_matched = sum(!is.na(rel)),
    .by = date
  ) |&gt;
  arrange(date) |&gt;
  mutate(
    gm    = replace_when(gm, is.na(gm) ~ 1),        # first month has no relative
    index = 100 * cumprod(gm)
  )


naive_index &lt;- wheat_national |&gt;
  arrange(date) |&gt;
  filter(!is.na(price_pkr)) |&gt;
  mutate(index = 100 * price_pkr / first(price_pkr)) |&gt;
  select(date, index) |&gt;
  mutate(method = "Naive cross-market mean")

bind_rows(
  naive_index,
  wheat_chained |&gt; select(date, index) |&gt; mutate(method = "Matched-sample chained")
) |&gt;
  ggplot(aes(date, index, colour = method)) +
  geom_line(linewidth = 0.7) +
  labs(
    title    = "Why composition matters",
    subtitle = "Two wheat flour indices from identical raw data",
    x = NULL, y = "Index (first month = 100)", colour = NULL
  )

If the two lines diverge materially, the naive average was measuring changes in who reported, not changes in what things cost. Show this plot to anyone who asks why your numbers differ from a published series.

12.4 Indexing each market to its own start
Useful for a different question: which markets have seen the steepest increases?

wheat_market_index &lt;- wheat_market |&gt;
  filter(!is.na(price_pkr)) |&gt;
  arrange(market, date) |&gt;
  mutate(index = 100 * price_pkr / first(price_pkr), .by = market)

Because mutate() with .by does not reorder rows, the arrange() beforehand is load-bearing. first() returns the first row as the data is currently sorted — this is a classic silent error.

14.1 Inspect before you join
Natural Earth uses its own spellings, and they change between releases. Always look first.

pak_states &lt;- ne_states(country = "Pakistan", returnclass = "sf") |&gt; st_make_valid()
ind_states &lt;- ne_states(country = "India",    returnclass = "sf") |&gt; st_make_valid()

pak_states |&gt;
  st_drop_geometry() |&gt;
  distinct(name, type_en) |&gt;
  arrange(name) |&gt;
  print(n = Inf)

ind_states |&gt;
  st_drop_geometry() |&gt;
  distinct(name) |&gt;
  filter(str_detect(name, regex("kashmir|jammu|ladakh", ignore_case = TRUE)))

Depending on your Natural Earth vintage you will see the Pakistan-administered units as Azad Kashmir and either Northern Areas or Gilgit-Baltistan, and the India-administered unit as Jammu and Kashmir (possibly split into Ladakh in newer releases). The lookup table we built in Section 6 already handles both spellings — this is the payoff for centralising the crosswalk.

14.2 Assemble the base map

pak_admin &lt;- pak_states |&gt;
  mutate(
    province = recode_values(
      name,
      from = province_lookup$from,
      to   = province_lookup$to
    ),
    status = "Administered by Pakistan"
  ) |&gt;
  select(province, status, geometry)

# Anything Natural Earth calls something our lookup does not know
pak_admin |&gt; st_drop_geometry() |&gt; filter(is.na(province))


jk_geometry &lt;- ind_states |&gt;
  filter(str_detect(name, regex("jammu|kashmir|ladakh", ignore_case = TRUE))) |&gt;
  st_geometry() |&gt;
  st_union()                                    # dissolve into one polygon

jammu_kashmir &lt;- st_sf(
  province = "Jammu & Kashmir",
  status   = "Disputed territory — no reporting market",
  geometry = jk_geometry
)

base_map &lt;- bind_rows(pak_admin, jammu_kashmir) |&gt;
  st_as_sf()

st_crs(base_map)
base_map |&gt; st_drop_geometry() |&gt; count(status)

Two details:

st_union() dissolves Jammu & Kashmir and Ladakh into a single region so the internal administrative line does not appear on a Pakistani map.
bind_rows() on sf objects works, but the result can lose its sf class in some combinations — the trailing st_as_sf() is cheap insurance.

14.3 Check the geography joins to the data

province_recent &lt;- province_year |&gt;
  filter(str_detect(commodity, regex("^wheat flour", ignore_case = TRUE))) |&gt;
  filter(year == max(year)) |&gt;
  summarise(price_pkr = mean(price_pkr, na.rm = TRUE), .by = province)

# Provinces in the data with no polygon — a real error, must be empty
province_recent |&gt;
  anti_join(st_drop_geometry(base_map), by = join_by(province))

# Polygons with no data — expected, and the point of this section
base_map |&gt;
  st_drop_geometry() |&gt;
  anti_join(province_recent, by = join_by(province))

The first anti-join must return zero rows. If it does not, your recode is incomplete and part of your data is falling off the map — literally. The second anti-join is supposed to return rows: Jammu & Kashmir, and any province where no market reported this year. Those become the grey areas.

